y_required":false},{"key":"chemical","code":"P1-MOCK-ACC2B31A-ETOH70","name":"Dung dịch ethanol 70% dùng thực hành — MOCK","uom":"p1-mock-acc2b31a_ml","uom_name":"mL (MOCK)","tracking_strategy":"quantity","return_semantics":"nonreturnable","material_kind":"chemical","expiry_required":true}],"opening":{"reference":"P1-MOCK-ACC2B31A-OPEN-V1","synthetic":true,"scope_description":"SYNTHETIC MOCK P1 rehearsal; not operational stock","provenance_note":"Fabricated training count only; no production source or real physical stock","rows":[{"row_key":"gloves","item_key":"consumable","good_quantity":"100","damaged_quantity":"5","base_quantity":"105","expiry_precision":"not_required"},{"row_key":"trays","item_key":"reusable","good_quantity":"12","damaged_quantity":"1","base_quantity":"13","expiry_precision":"not_required"},{"row_key":"ethanol-day","item_key":"chemical","good_quantity":"1000","damaged_quantity":"0","base_quantity":"1000","expiry_precision":"day","expiry_input":"2027-12-31"},{"row_key":"ethanol-month","item_key":"chemical","good_quantity":"250","damaged_quantity":"0","base_quantity":"250","expiry_precision":"month","expiry_input":"2028-03"},{"row_key":"ethanol-unknown","item_key":"chemical","good_quantity":"100","damaged_quantity":"0","base_quantity":"100","expiry_precision":"unknown"},{"row_key":"ethanol-expired","item_key":"chemical","good_quantity":"50","damaged_quantity":"0","base_quantity":"50","expiry_precision":"day","expiry_input":"2026-09-30"}]},"asset":{"row_key":"pump-001","manufacturer":"MedLabs Training Devices — MOCK","model":"IP-100 training","manufacturer_serial":"P1-MOCK-ACC2B31A-IP100-001","operational_status":"ready","expiry_precision":"not_required","synthetic":true},"writer_register":[{"writer":"pilot RPC","model_status":"allowed only per phase and frozen mock scope"},{"writer":"legacy/current MedLabs","model_status":"excluded in simulation; no real writer read/freeze/change"},{"writer":"import/privileged/manual","model_status":"excluded in simulation; no real exclusion proof"}]}'::jsonb);
create function pg_temp.p1_assert(ok boolean,message text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'P1_MOCK_ASSERT: %',message; end if; end; $$;
create function pg_temp.p1_expect(operation text,payload jsonb,retry uuid,prefix text,asset boolean default false) returns void language plpgsql as $$
begin
 begin
  if asset then perform public.equipment_asset_command(operation,payload,retry); else perform public.inventory_command(operation,payload,retry); end if;
 exception when others then
  if position(prefix in sqlerrm)=1 then return; end if;
  raise;
 end;
 raise exception 'P1_MOCK_EXPECTED_DENIAL: %',prefix;
end; $$;
select pg_temp.p1_assert(not exists(select 1 from public.inventory_catalog_items where code like 'P1-MOCK-ACC2B31A%'),'scope already exists; use recorded manifest, never reseed');
