select pg_temp.p1_assert(public.inventory_command('confirm_opening_balance',(select value from p1_mock_context where key='opening-payload'),'97df21fa-50f4-4011-8b2e-2aefc75ed409')=(select value from p1_mock_context where key='opening-result'),'opening replay IDs changed');
select pg_temp.p1_expect('confirm_opening_balance',(select value||'{"provenance_note":"changed payload"}'::jsonb from p1_mock_context where key='opening-payload'),'97df21fa-50f4-4011-8b2e-2aefc75ed409','RETRY_PAYLOAD_MISMATCH');
select pg_temp.p1_expect('confirm_opening_balance',(select value from p1_mock_context where key='opening-payload'),gen_random_uuid(),'BUSINESS_DUPLICATE');
