select pg_temp.p1_assert(public.equipment_asset_command('open_asset',(select value from p1_mock_context where key='asset-payload'),'431c6bd8-cd39-403c-9eed-6c7fe91df288')=(select value from p1_mock_context where key='asset-result'),'asset replay IDs changed');
