reset role;
select pg_temp.p1_assert((select count(*)=6 from public.inventory_stock_origins where opening_batch_id=(select (value->>'opening_batch_id')::uuid from p1_mock_context where key='opening-result')),'opening origin count');
select pg_temp.p1_assert((select synthetic from public.inventory_opening_batches where id=(select (value->>'opening_batch_id')::uuid from p1_mock_context where key='opening-result')),'opening not synthetic');
select pg_temp.p1_assert(not exists(select 1 from public.inventory_stock_balances b join public.inventory_stock_origins o on o.id=b.cohort_id where o.catalog_item_id=(select (value->>'id')::uuid from p1_mock_context where key='item-serialized')),'serialized asset double-counted');
select pg_temp.p1_assert(not exists(select 1 from public.inventory_stock_balances b join public.inventory_stock_origins o on o.id=b.cohort_id where o.opening_batch_id=(select (value->>'opening_batch_id')::uuid from p1_mock_context where key='opening-result') and b.quantity<>(select coalesce(sum(l.quantity_delta),0) from public.inventory_transaction_lines l where l.cohort_id=b.cohort_id and l.location_id=b.location_id and l.condition=b.condition)),'balance ledger mismatch');
select pg_temp.p1_assert((select count(*)=1 from public.equipment_assets where id=(select (value->>'id')::uuid from p1_mock_context where key='asset-result') and manufacturer_serial='P1-MOCK-ACC2B31A-IP100-001' and operational_status='ready' and lifecycle_status='in_service'),'exact asset state/identity');
insert into p1_mock_context select 'facts',jsonb_agg(jsonb_build_object('origin_id',o.id,'cohort_id',o.id,'row_key',o.line_key,'item_id',o.catalog_item_id,'base_quantity',f.base_quantity::text,'good_quantity',f.good_quantity::text,'damaged_quantity',f.damaged_quantity::text,'expiry_precision',f.expiry_precision,'expiry_date',f.expiry_date,'available_quantity',private.s4_available(o.id,f.location_id)::text) order by o.line_key) from public.inventory_stock_origins o join public.inventory_receipt_cohorts c on c.origin_id=o.id join public.inventory_stock_facts f on f.id=c.current_fact_id where o.opening_batch_id=(select (value->>'opening_batch_id')::uuid from p1_mock_context where key='opening-result');
select pg_temp.p1_assert((select (f->>'available_quantity')::numeric=0 from p1_mock_context cross join jsonb_array_elements(value) f where key='facts' and f->>'row_key'='ethanol-unknown'),'unknown expiry available');
select pg_temp.p1_assert((select (f->>'available_quantity')::numeric=0 from p1_mock_context cross join jsonb_array_elements(value) f where key='facts' and f->>'row_key'='ethanol-expired'),'expired stock available');
select pg_temp.p1_assert((select f->>'expiry_date'='2028-03-31' from p1_mock_context cross join jsonb_array_elements(value) f where key='facts' and f->>'row_key'='ethanol-month'),'month expiry not month-end');
select pg_temp.p1_assert((select count(*)=3 from public.inventory_opening_scope where opening_batch_id=(select (value->>'opening_batch_id')::uuid from p1_mock_context where key='opening-result')),'wrong quantity opening scope');
select pg_temp.p1_assert(not exists(
  select 1 from jsonb_array_elements((select value->'opening'->'rows' from p1_mock_context where key='manifest')) expected
  left join jsonb_array_elements((select value from p1_mock_context where key='facts')) actual on actual->>'row_key'=expected->>'row_key'
  where actual is null
    or (actual->>'base_quantity')::numeric<>(expected->>'base_quantity')::numeric
    or (actual->>'good_quantity')::numeric<>(expected->>'good_quantity')::numeric
    or (actual->>'damaged_quantity')::numeric<>(expected->>'damaged_quantity')::numeric
    or actual->>'expiry_precision'<>expected->>'expiry_precision'
    or (actual->>'available_quantity')::numeric<>case when expected->>'expiry_precision'='unknown' or expected->>'row_key'='ethanol-expired' then 0 else (expected->>'good_quantity')::numeric end
),'opening quantities/condition/expiry eligibility differ from manifest');
select (select value from p1_mock_context where key='manifest')||jsonb_build_object('location',(select value from p1_mock_context where key='manifest')->'location'||(select value from p1_mock_context where key='location'),'items',(select jsonb_agg(i||jsonb_build_object('id',(select value->>'id' from p1_mock_context where key='item-'||(i->>'key'))) order by i->>'key') from jsonb_array_elements((select value->'items' from p1_mock_context where key='manifest')) i),'opening_payload',(select value from p1_mock_context where key='opening-payload'),'opening_result',(select value from p1_mock_context where key='opening-result'),'asset',(select value from p1_mock_context where key='manifest')->'asset'||(select value from p1_mock_context where key='asset-commission'),'asset_opening_result',(select value from p1_mock_context where key='asset-result'),'facts',(select value from p1_mock_context where key='facts'),'balances_read',(select value from p1_mock_context where key='balances-read'),'database_checks','PASS; failure would rollback entire fixture') as manifest;
commit;